package ae.crdt;

import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;

/** Grow-only counter: one monotonic slot per replica; merge takes the pointwise maximum. */
public final class GCounter {
    private static final GCounter EMPTY = new GCounter(Map.of());
    private final Map<String, Long> slots;

    private GCounter(Map<String, Long> slots) {
        this.slots = slots;
    }

    public static GCounter empty() {
        return EMPTY;
    }

    public GCounter increment(String replica, long n) {
        Objects.requireNonNull(replica);
        if (replica.isEmpty()) {
            throw new IllegalArgumentException("empty replica id");
        }
        if (n < 0) {
            throw new IllegalArgumentException("negative increment");
        }
        if (n == 0) {
            return this;
        }
        Map<String, Long> copy = new TreeMap<>(slots);
        copy.merge(replica, n, Math::addExact);
        return new GCounter(Map.copyOf(copy));
    }

    public long value() {
        long sum = 0;
        for (long v : slots.values()) {
            sum = Math.addExact(sum, v);
        }
        return sum;
    }

    public GCounter merge(GCounter other) {
        Map<String, Long> copy = new TreeMap<>(slots);
        other.slots.forEach((k, v) -> copy.merge(k, v, Math::max));
        return new GCounter(Map.copyOf(copy));
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof GCounter g && slots.equals(g.slots);
    }

    @Override
    public int hashCode() {
        return slots.hashCode();
    }

    @Override
    public String toString() {
        return "GCounter" + new TreeMap<>(slots);
    }
}

package ae.crdt;

import java.util.Objects;
import java.util.Optional;

/** Last-writer-wins register ordered by (time, replica id, string form of the value). */
public final class LwwRegister<T> {
    private static final LwwRegister<?> EMPTY = new LwwRegister<>(null, 0, "", false);
    private final T value;
    private final long time;
    private final String replica;
    private final boolean present;

    private LwwRegister(T value, long time, String replica, boolean present) {
        this.value = value;
        this.time = time;
        this.replica = replica;
        this.present = present;
    }

    @SuppressWarnings("unchecked")
    public static <T> LwwRegister<T> empty() {
        return (LwwRegister<T>) EMPTY;
    }

    /** Writes value with the given stamp; an older stamp than the current one loses. */
    public LwwRegister<T> set(T newValue, long newTime, String newReplica) {
        Objects.requireNonNull(newValue);
        Objects.requireNonNull(newReplica);
        return merge(new LwwRegister<>(newValue, newTime, newReplica, true));
    }

    public Optional<T> get() {
        return present ? Optional.of(value) : Optional.empty();
    }

    public LwwRegister<T> merge(LwwRegister<T> other) {
        if (!present) {
            return other;
        }
        if (!other.present) {
            return this;
        }
        return compare(other) >= 0 ? this : other;
    }

    private int compare(LwwRegister<T> o) {
        int c = Long.compare(time, o.time);
        if (c == 0) {
            c = replica.compareTo(o.replica);
        }
        if (c == 0) {
            c = String.valueOf(value).compareTo(String.valueOf(o.value));
        }
        return c;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof LwwRegister<?> r)) {
            return false;
        }
        if (!present || !r.present) {
            return present == r.present;
        }
        return time == r.time && replica.equals(r.replica) && value.equals(r.value);
    }

    @Override
    public int hashCode() {
        return present ? Objects.hash(value, time, replica) : 0;
    }
}

package ae.crdt;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Observed-remove set with add-wins semantics. Every add mints a unique tag; a remove
 * tombstones only the tags its replica has observed, so a concurrent add survives.
 */
public final class OrSet<E> {
    /** Unique identity of one add operation. */
    public record Tag(String replica, long counter) { }

    private record Entry<E>(E element, Tag tag) { }

    private static final OrSet<?> EMPTY = new OrSet<>(Set.of(), Set.of(), Map.of());
    private final Set<Entry<E>> entries;
    private final Set<Tag> tombstones;
    private final Map<String, Long> clock;

    private OrSet(Set<Entry<E>> entries, Set<Tag> tombstones, Map<String, Long> clock) {
        this.entries = entries;
        this.tombstones = tombstones;
        this.clock = clock;
    }

    @SuppressWarnings("unchecked")
    public static <E> OrSet<E> empty() {
        return (OrSet<E>) EMPTY;
    }

    public OrSet<E> add(E element, String replica) {
        Objects.requireNonNull(element);
        if (replica == null || replica.isEmpty()) {
            throw new IllegalArgumentException("bad replica id");
        }
        long next = clock.getOrDefault(replica, 0L) + 1;
        Set<Entry<E>> e = new HashSet<>(entries);
        e.add(new Entry<>(element, new Tag(replica, next)));
        Map<String, Long> c = new HashMap<>(clock);
        c.put(replica, next);
        return new OrSet<>(Set.copyOf(e), tombstones, Map.copyOf(c));
    }

    /** Removes the element's currently observed tags; absent element returns this. */
    public OrSet<E> remove(E element) {
        Set<Tag> observed = entries.stream()
                .filter(en -> en.element().equals(element))
                .map(Entry::tag)
                .collect(Collectors.toSet());
        if (tombstones.containsAll(observed)) {
            return this;
        }
        Set<Tag> t = new HashSet<>(tombstones);
        t.addAll(observed);
        return new OrSet<>(entries, Set.copyOf(t), clock);
    }

    public boolean contains(E element) {
        return entries.stream().anyMatch(en -> en.element().equals(element) && !tombstones.contains(en.tag()));
    }

    public Set<E> elements() {
        return entries.stream().filter(en -> !tombstones.contains(en.tag()))
                .map(Entry::element).collect(Collectors.toUnmodifiableSet());
    }

    public OrSet<E> merge(OrSet<E> other) {
        Set<Entry<E>> e = new HashSet<>(entries);
        e.addAll(other.entries);
        Set<Tag> t = new HashSet<>(tombstones);
        t.addAll(other.tombstones);
        Map<String, Long> c = new HashMap<>(clock);
        other.clock.forEach((k, v) -> c.merge(k, v, Math::max));
        return new OrSet<>(Set.copyOf(e), Set.copyOf(t), Map.copyOf(c));
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof OrSet<?> s && entries.equals(s.entries) && tombstones.equals(s.tombstones)
                && clock.equals(s.clock);
    }

    @Override
    public int hashCode() {
        return Objects.hash(entries, tombstones, clock);
    }
}

package ae.crdt;

/** Counter supporting decrements: a pair of grow-only counters (increments, decrements). */
public record PNCounter(GCounter pos, GCounter neg) {
    private static final PNCounter EMPTY = new PNCounter(GCounter.empty(), GCounter.empty());

    public static PNCounter empty() {
        return EMPTY;
    }

    public PNCounter increment(String replica, long n) {
        return new PNCounter(pos.increment(replica, n), neg);
    }

    public PNCounter decrement(String replica, long n) {
        return new PNCounter(pos, neg.increment(replica, n));
    }

    public long value() {
        return Math.subtractExact(pos.value(), neg.value());
    }

    public PNCounter merge(PNCounter other) {
        return new PNCounter(pos.merge(other.pos), neg.merge(other.neg));
    }
}

