package ae.crdt;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.Random;
import org.junit.jupiter.api.Test;

class CounterTest {
    @Test
    void gCounterSumsReplicas() {
        GCounter g = GCounter.empty().increment("a", 3).increment("b", 4).increment("a", 2);
        assertEquals(9, g.value());
    }

    @Test
    void concurrentIncrementsAddUpAfterMerge() {
        GCounter a = GCounter.empty().increment("a", 5);
        GCounter b = GCounter.empty().increment("b", 7);
        assertEquals(12, a.merge(b).value());
        assertEquals(12, b.merge(a).value());
    }

    @Test
    void mergingStaleCopyDoesNotLoseOrDoubleCount() {
        GCounter old = GCounter.empty().increment("a", 2);
        GCounter newer = old.increment("a", 3);
        assertEquals(5, newer.merge(old).value());
        assertEquals(5, old.merge(newer).value());
        assertEquals(5, newer.merge(newer).value());
    }

    @Test
    void zeroIncrementIsNoOpAndBadArgsRejected() {
        GCounter g = GCounter.empty().increment("a", 1);
        assertSame(g, g.increment("a", 0));
        assertThrows(IllegalArgumentException.class, () -> g.increment("a", -1));
        assertThrows(IllegalArgumentException.class, () -> g.increment("", 1));
        assertThrows(NullPointerException.class, () -> g.increment(null, 1));
    }

    @Test
    void overflowIsDetected() {
        GCounter g = GCounter.empty().increment("a", Long.MAX_VALUE);
        assertThrows(ArithmeticException.class, () -> g.increment("a", 1));
        GCounter two = g.increment("b", 1);
        assertThrows(ArithmeticException.class, two::value);
    }

    @Test
    void pnCounterGoesNegativeAndMerges() {
        PNCounter a = PNCounter.empty().increment("a", 2).decrement("a", 5);
        PNCounter b = PNCounter.empty().decrement("b", 4).increment("b", 1);
        assertEquals(-3, a.value());
        assertEquals(-3, b.value());
        assertEquals(-6, a.merge(b).value());
        assertEquals(a.merge(b), b.merge(a));
    }

    @Test
    void gCounterMergeLawsOnRandomStates() {
        Random rnd = new Random(42);
        for (int i = 0; i < 300; i++) {
            GCounter x = random(rnd);
            GCounter y = random(rnd);
            GCounter z = random(rnd);
            assertEquals(x.merge(y), y.merge(x), "commutative");
            assertEquals(x.merge(y).merge(z), x.merge(y.merge(z)), "associative");
            assertEquals(x, x.merge(x), "idempotent");
            assertEquals(true, x.merge(y).value() >= Math.max(x.value(), y.value()), "monotonic");
        }
    }

    private static GCounter random(Random rnd) {
        GCounter g = GCounter.empty();
        for (int k = rnd.nextInt(6); k > 0; k--) {
            g = g.increment("r" + rnd.nextInt(3), rnd.nextInt(10));
        }
        return g;
    }
}

package ae.crdt;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import org.junit.jupiter.api.Test;

/** Replicas apply random local ops and gossip random merges; after full exchange all agree. */
class GossipSimulationTest {
    private static final int REPLICAS = 5;

    @Test
    void pnCounterConvergesToOracleSum() {
        for (long seed = 1; seed <= 40; seed++) {
            Random rnd = new Random(seed);
            PNCounter[] st = new PNCounter[REPLICAS];
            java.util.Arrays.fill(st, PNCounter.empty());
            long oracle = 0;
            for (int step = 0; step < 200; step++) {
                int r = rnd.nextInt(REPLICAS);
                if (rnd.nextInt(3) == 0) {
                    int from = rnd.nextInt(REPLICAS);
                    st[r] = st[r].merge(st[from]);
                } else {
                    int n = rnd.nextInt(5);
                    if (rnd.nextBoolean()) {
                        st[r] = st[r].increment("r" + r, n);
                        oracle += n;
                    } else {
                        st[r] = st[r].decrement("r" + r, n);
                        oracle -= n;
                    }
                }
            }
            PNCounter all = PNCounter.empty();
            for (PNCounter s : st) {
                all = all.merge(s);
            }
            assertEquals(oracle, all.value(), "seed " + seed);
            for (PNCounter s : st) {
                assertEquals(all, s.merge(all), "seed " + seed);
            }
        }
    }

    @Test
    void orSetConvergesAndMatchesAddWinsOracle() {
        for (long seed = 1; seed <= 60; seed++) {
            Random rnd = new Random(seed);
            @SuppressWarnings("unchecked")
            OrSet<Integer>[] st = new OrSet[REPLICAS];
            java.util.Arrays.fill(st, OrSet.<Integer>empty());
            // oracle: all add tags ever made per element, and which tags each remove observed
            Map<Integer, Set<String>> tagsOf = new HashMap<>();
            Set<String> dead = new HashSet<>();
            @SuppressWarnings("unchecked")
            Set<String>[] seen = new Set[REPLICAS];
            for (int i = 0; i < REPLICAS; i++) {
                seen[i] = new HashSet<>();
            }
            int[] counter = new int[REPLICAS];
            for (int step = 0; step < 150; step++) {
                int r = rnd.nextInt(REPLICAS);
                int op = rnd.nextInt(10);
                int e = rnd.nextInt(4);
                if (op < 4) {
                    st[r] = st[r].add(e, "r" + r);
                    String tag = "r" + r + ":" + (++counter[r]);
                    tagsOf.computeIfAbsent(e, k -> new HashSet<>()).add(tag);
                    seen[r].add(tag + "@" + e);
                } else if (op < 6) {
                    st[r] = st[r].remove(e);
                    for (String t : seen[r]) {
                        if (t.endsWith("@" + e)) {
                            dead.add(t);
                        }
                    }
                } else {
                    int from = rnd.nextInt(REPLICAS);
                    st[r] = st[r].merge(st[from]);
                    seen[r].addAll(seen[from]);
                }
            }
            OrSet<Integer> all = OrSet.empty();
            for (OrSet<Integer> s : st) {
                all = all.merge(s);
            }
            Set<Integer> expected = new HashSet<>();
            for (var en : tagsOf.entrySet()) {
                for (String tag : en.getValue()) {
                    if (!dead.contains(tag + "@" + en.getKey())) {
                        expected.add(en.getKey());
                    }
                }
            }
            assertEquals(expected, all.elements(), "seed " + seed);
            for (OrSet<Integer> s : st) {
                assertEquals(all, s.merge(all), "converged state, seed " + seed);
                assertEquals(all, all.merge(s), "seed " + seed);
            }
        }
    }

    @Test
    void orSetMergeLawsOnRandomStates() {
        Random rnd = new Random(7);
        for (int i = 0; i < 200; i++) {
            OrSet<Integer> x = randomSet(rnd);
            OrSet<Integer> y = randomSet(rnd);
            OrSet<Integer> z = randomSet(rnd);
            assertEquals(x.merge(y), y.merge(x));
            assertEquals(x.merge(y).merge(z), x.merge(y.merge(z)));
            assertEquals(x, x.merge(x));
        }
    }

    private static OrSet<Integer> randomSet(Random rnd) {
        OrSet<Integer> s = OrSet.empty();
        for (int k = rnd.nextInt(8); k > 0; k--) {
            if (rnd.nextInt(3) == 0) {
                s = s.remove(rnd.nextInt(4));
            } else {
                s = s.add(rnd.nextInt(4), "r" + rnd.nextInt(3));
            }
        }
        return s;
    }
}

package ae.crdt;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;
import org.junit.jupiter.api.Test;

class OrSetTest {
    @Test
    void addContainsRemove() {
        OrSet<String> s = OrSet.<String>empty().add("x", "a");
        assertTrue(s.contains("x"));
        assertEquals(Set.of("x"), s.elements());
        OrSet<String> r = s.remove("x");
        assertFalse(r.contains("x"));
        assertEquals(Set.of(), r.elements());
        assertEquals(Set.of("x"), s.elements(), "original untouched");
    }

    @Test
    void concurrentAddBeatsRemove() {
        OrSet<String> base = OrSet.<String>empty().add("x", "a");
        OrSet<String> remover = base.remove("x");
        OrSet<String> adder = base.add("x", "b");
        assertEquals(Set.of("x"), remover.merge(adder).elements());
        assertEquals(Set.of("x"), adder.merge(remover).elements());
    }

    @Test
    void removeOfUnobservedAddDoesNotKillIt() {
        OrSet<String> a = OrSet.<String>empty().add("x", "a");
        OrSet<String> b = OrSet.<String>empty().remove("x");
        assertTrue(a.merge(b).contains("x"));
        assertEquals(b, b.remove("x"));
    }

    @Test
    void reAddAfterRemoveWorksAndSurvivesMergeWithOldState() {
        OrSet<String> s = OrSet.<String>empty().add("x", "a");
        OrSet<String> removed = s.remove("x");
        OrSet<String> readded = removed.add("x", "a");
        assertTrue(readded.contains("x"));
        assertTrue(readded.merge(s).contains("x"));
        assertTrue(s.merge(readded).contains("x"));
        assertFalse(removed.merge(s).contains("x"), "old add stays dead after remove");
    }

    @Test
    void sameReplicaTagsNeverCollide() {
        OrSet<String> s = OrSet.<String>empty().add("x", "a").remove("x").add("y", "a");
        OrSet<String> t = s.add("x", "a");
        assertEquals(Set.of("x", "y"), t.elements());
    }

    @Test
    void duplicateConcurrentAddsNeedBothRemoved() {
        OrSet<String> a = OrSet.<String>empty().add("x", "a");
        OrSet<String> b = OrSet.<String>empty().add("x", "b");
        OrSet<String> both = a.merge(b);
        // a removes after seeing only its own add; b's add survives
        OrSet<String> aRemoved = a.remove("x");
        assertTrue(aRemoved.merge(b).contains("x"));
        assertFalse(both.remove("x").contains("x"));
    }
}

package ae.crdt;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Optional;
import org.junit.jupiter.api.Test;

class RegisterTest {
    @Test
    void emptyHasNoValueAndIsMergeIdentity() {
        LwwRegister<String> e = LwwRegister.empty();
        LwwRegister<String> r = e.set("x", 1, "a");
        assertEquals(Optional.empty(), e.get());
        assertEquals(r, e.merge(r));
        assertEquals(r, r.merge(e));
    }

    @Test
    void laterTimeWinsRegardlessOfMergeOrder() {
        LwwRegister<String> a = LwwRegister.<String>empty().set("old", 5, "a");
        LwwRegister<String> b = LwwRegister.<String>empty().set("new", 9, "b");
        assertEquals(Optional.of("new"), a.merge(b).get());
        assertEquals(Optional.of("new"), b.merge(a).get());
    }

    @Test
    void sameTimeBrokenByReplicaId() {
        LwwRegister<String> a = LwwRegister.<String>empty().set("fromA", 5, "a");
        LwwRegister<String> b = LwwRegister.<String>empty().set("fromB", 5, "b");
        assertEquals(Optional.of("fromB"), a.merge(b).get());
        assertEquals(Optional.of("fromB"), b.merge(a).get());
    }

    @Test
    void fullStampTieBrokenByValueAndStaysCommutative() {
        LwwRegister<String> a = LwwRegister.<String>empty().set("apple", 5, "a");
        LwwRegister<String> b = LwwRegister.<String>empty().set("banana", 5, "a");
        assertEquals(a.merge(b), b.merge(a));
        assertEquals(Optional.of("banana"), a.merge(b).get());
    }

    @Test
    void staleWriteLosesLocally() {
        LwwRegister<Integer> r = LwwRegister.<Integer>empty().set(1, 10, "a").set(2, 3, "a");
        assertEquals(Optional.of(1), r.get());
    }

    @Test
    void lawsOverAllStampCombinations() {
        String[] reps = {"a", "b"};
        java.util.List<LwwRegister<Integer>> all = new java.util.ArrayList<>();
        all.add(LwwRegister.empty());
        for (long t = 1; t <= 2; t++) {
            for (String rp : reps) {
                for (int v = 0; v < 2; v++) {
                    all.add(LwwRegister.<Integer>empty().set(v, t, rp));
                }
            }
        }
        assertEquals(9, all.size());
        for (var x : all) {
            assertEquals(x, x.merge(x));
            for (var y : all) {
                assertEquals(x.merge(y), y.merge(x));
                for (var z : all) {
                    assertEquals(x.merge(y).merge(z), x.merge(y.merge(z)));
                }
            }
        }
        assertTrue(all.get(0).equals(LwwRegister.<Integer>empty()));
    }
}
